import React, { useEffect, useMemo, useState } from 'react';
import { Copy, KeyRound, Search, ShieldCheck, ShieldOff, Trash2, UserPlus } from 'lucide-react';
import { api } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { Card, EmptyRow, ErrorNote, Field, Modal, PageHeader, Spinner, inputClass, primaryBtn, secondaryBtn, useToast } from './tracking/shared';

// Admin → Staff Access: logins for trainers and the placement team. Passwords are generated by the system,
// shown once, and only an admin can reset them.

type Role = 'ADMIN' | 'TRAINER' | 'PLACEMENT_MANAGER';
interface Staff {
  _id: string;
  fullName: string;
  email: string;
  role: Role;
  isActive: boolean;
  createdAt: string;
  passwordChangedAt: string;
  createdBy: string;
}

const ROLE_LABEL: Record<Role, string> = { ADMIN: 'Admin', TRAINER: 'Trainer', PLACEMENT_MANAGER: 'Placement team' };
const ROLE_OPTIONS: Role[] = ['TRAINER', 'PLACEMENT_MANAGER', 'ADMIN'];
const fmt = (d: string) => new Date(d).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });

// Shown once after create / reset: the only time anyone sees the password
const PasswordReveal: React.FC<{ staff: Staff; password: string; onClose: () => void }> = ({ staff, password, onClose }) => {
  const [copied, setCopied] = useState(false);
  const loginText = `ScholarLogic login\nWebsite: ${window.location.origin}\nLogin ID: ${staff.email}\nPassword: ${password}`;
  const copy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      // Clipboard blocked: the details stay on screen to copy by hand
    }
  };
  return (
    <Modal title={`Login for ${staff.fullName}`} subtitle="Copy this now and send it to them privately. The password will not be shown again." onClose={onClose}>
      <div className="space-y-4">
        <dl className="grid grid-cols-[7rem_minmax(0,1fr)] gap-y-2 rounded-xl bg-slate-50 dark:bg-slate-800/60 p-4 text-sm">
          <dt className="text-slate-500">Role</dt>
          <dd className="font-semibold text-slate-900 dark:text-white">{ROLE_LABEL[staff.role]}</dd>
          <dt className="text-slate-500">Login ID</dt>
          <dd className="font-mono text-slate-900 dark:text-white break-all">{staff.email}</dd>
          <dt className="text-slate-500">Password</dt>
          <dd className="font-mono text-lg font-bold tracking-wide text-brand-700 dark:text-brand-300 break-all select-all">{password}</dd>
        </dl>
        <p className="text-xs text-slate-500">They cannot change this password themselves. If it is lost, use "Reset password" here to generate a new one.</p>
        <div className="flex flex-wrap justify-end gap-2">
          <button type="button" className={secondaryBtn} onClick={() => copy(password)}>
            <Copy className="h-3.5 w-3.5" /> Copy password
          </button>
          <button type="button" className={primaryBtn} onClick={() => copy(loginText)}>
            <Copy className="h-3.5 w-3.5" /> {copied ? 'Copied' : 'Copy login details'}
          </button>
          <button type="button" className={secondaryBtn} onClick={onClose}>
            Done
          </button>
        </div>
      </div>
    </Modal>
  );
};

export const AdminStaff: React.FC = () => {
  const toast = useToast();
  const { user: me } = useAuth();
  const isMe = (s: { _id: string }) => s._id === ((me as any)?.id || (me as any)?._id);
  const [staff, setStaff] = useState<Staff[] | null>(null);
  const [error, setError] = useState('');
  const [q, setQ] = useState('');
  const [roleFilter, setRoleFilter] = useState<'' | Role>('');
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState({ fullName: '', email: '', role: 'TRAINER' as Role });
  const [formError, setFormError] = useState('');
  const [busy, setBusy] = useState('');
  const [reveal, setReveal] = useState<{ staff: Staff; password: string } | null>(null);
  const [confirm, setConfirm] = useState<{ kind: 'reset' | 'remove' | 'delete'; staff: Staff } | null>(null);

  const load = () =>
    api
      .get('/admin/staff')
      .then((res: any) => setStaff(res.data.staff))
      .catch((e: any) => setError(e.message));
  useEffect(() => {
    load();
  }, []);

  const visible = useMemo(() => {
    const term = q.trim().toLowerCase();
    return (staff || []).filter((s) => (!roleFilter || s.role === roleFilter) && (!term || `${s.fullName} ${s.email}`.toLowerCase().includes(term)));
  }, [staff, q, roleFilter]);

  const create = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy('new');
    setFormError('');
    try {
      const res: any = await api.post('/admin/staff', form);
      setAdding(false);
      setForm({ fullName: '', email: '', role: 'TRAINER' });
      setReveal({ staff: res.data.staff, password: res.data.password });
      load();
    } catch (err: any) {
      setFormError(err.message);
    } finally {
      setBusy('');
    }
  };

  const resetPassword = async (s: Staff) => {
    setBusy(s._id);
    try {
      const res: any = await api.post(`/admin/staff/${s._id}/reset-password`, {});
      setConfirm(null);
      setReveal({ staff: res.data.staff, password: res.data.password });
      load();
    } catch (e: any) {
      toast.show(e.message);
    } finally {
      setBusy('');
    }
  };

  const setActive = async (s: Staff, isActive: boolean) => {
    setBusy(s._id);
    try {
      const res: any = await api.put(`/admin/staff/${s._id}`, { isActive });
      setConfirm(null);
      toast.show(res.message);
      load();
    } catch (e: any) {
      toast.show(e.message);
    } finally {
      setBusy('');
    }
  };

  const deleteAccount = async (s: Staff) => {
    setBusy(s._id);
    try {
      const res: any = await api.delete(`/admin/staff/${s._id}`);
      setConfirm(null);
      toast.show(res.message);
      load();
    } catch (e: any) {
      toast.show(e.message);
    } finally {
      setBusy('');
    }
  };

  const changeRole = async (s: Staff, role: Role) => {
    try {
      await api.put(`/admin/staff/${s._id}`, { role });
      toast.show(`${s.fullName} is now ${ROLE_LABEL[role]}`);
      load();
    } catch (e: any) {
      toast.show(e.message);
    }
  };

  const count = (r: Role) => (staff || []).filter((s) => s.role === r && s.isActive).length;

  return (
    <div className="space-y-5 pb-12">
      <PageHeader
        title="Staff Access"
        subtitle="Create logins for admins, trainers and the placement team. Passwords are generated for you and only an admin can reset them."
        action={
          <button type="button" className={primaryBtn} onClick={() => { setAdding(true); setFormError(''); }}>
            <UserPlus className="h-4 w-4" /> Give access
          </button>
        }
      />
      <ErrorNote text={error} />

      <Card className="p-4 space-y-3">
        <div className="flex flex-wrap items-center gap-2 text-xs">
          {([['', 'Everyone'], ['ADMIN', `Admins (${count('ADMIN')})`], ['TRAINER', `Trainers (${count('TRAINER')})`], ['PLACEMENT_MANAGER', `Placement team (${count('PLACEMENT_MANAGER')})`]] as [string, string][]).map(([k, l]) => (
            <button
              key={k || 'all'}
              type="button"
              onClick={() => setRoleFilter(k as any)}
              className={`rounded-full border px-3 py-1 font-semibold ${roleFilter === k ? 'border-brand-600 bg-brand-600 text-white' : 'border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300'}`}
            >
              {l}
            </button>
          ))}
        </div>
        <label className="relative block">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input id="staff-search" className={`${inputClass} pl-9`} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search name or email" />
        </label>
      </Card>

      {!staff ? (
        <Spinner />
      ) : (
        <Card className="overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[860px] text-left text-xs">
              <thead className="border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/60 text-[10px] font-bold uppercase text-slate-500">
                <tr>
                  {['Name', 'Login ID (email)', 'Role', 'Access', 'Password set', 'Actions'].map((h) => (
                    <th key={h} className="px-3 py-3 whitespace-nowrap">
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                {visible.length === 0 ? (
                  <EmptyRow colSpan={6} text={staff.length ? 'Nobody matches.' : 'No staff logins yet. Click "Give access".'} />
                ) : (
                  visible.map((s) => (
                    <tr key={s._id} className={`hover:bg-slate-50 dark:hover:bg-slate-800/40 ${s.isActive ? '' : 'opacity-60'}`}>
                      <td className="px-3 py-3 font-bold text-slate-900 dark:text-white whitespace-nowrap">
                        {s.fullName}
                        {s.createdBy && <span className="block text-[10px] font-normal text-slate-400">added by {s.createdBy}</span>}
                      </td>
                      <td className="px-3 py-3 font-mono">{s.email}</td>
                      <td className="px-3 py-3">
                        <select
                          id={`role-${s._id}`}
                          aria-label={`Role for ${s.fullName}`}
                          className={`${inputClass} !w-40 !py-1 text-xs`}
                          value={s.role}
                          disabled={!s.isActive || isMe(s)}
                          title={isMe(s) ? 'This is you' : undefined}
                          onChange={(e) => changeRole(s, e.target.value as Role)}
                        >
                          {ROLE_OPTIONS.map((r) => (
                            <option key={r} value={r}>
                              {ROLE_LABEL[r]}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td className="px-3 py-3 whitespace-nowrap">
                        {s.isActive ? (
                          <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 dark:bg-emerald-950/50 px-2 py-0.5 text-[10px] font-bold text-emerald-700 dark:text-emerald-300">
                            <ShieldCheck className="h-3 w-3" /> Can log in
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 rounded-full bg-rose-50 dark:bg-rose-950/50 px-2 py-0.5 text-[10px] font-bold text-rose-700 dark:text-rose-300">
                            <ShieldOff className="h-3 w-3" /> Access removed
                          </span>
                        )}
                      </td>
                      <td className="px-3 py-3 whitespace-nowrap text-slate-500">{fmt(s.passwordChangedAt)}</td>
                      <td className="px-3 py-3">
                        <div className="flex flex-wrap gap-2">
                          {isMe(s) ? (
                            <span className="text-[11px] text-slate-400">This is you. Change your password on Login &amp; Password.</span>
                          ) : s.isActive ? (
                            <>
                              <button type="button" className={`${secondaryBtn} !px-2.5 !py-1`} disabled={busy === s._id} onClick={() => setConfirm({ kind: 'reset', staff: s })}>
                                <KeyRound className="h-3.5 w-3.5" /> Reset password
                              </button>
                              <button
                                type="button"
                                className={`${secondaryBtn} !px-2.5 !py-1 !text-rose-600`}
                                disabled={busy === s._id}
                                onClick={() => setConfirm({ kind: 'remove', staff: s })}
                              >
                                <ShieldOff className="h-3.5 w-3.5" /> Remove access
                              </button>
                            </>
                          ) : (
                            <>
                              <button type="button" className={`${secondaryBtn} !px-2.5 !py-1`} disabled={busy === s._id} onClick={() => setActive(s, true)}>
                                <ShieldCheck className="h-3.5 w-3.5" /> Restore access
                              </button>
                              <button
                                type="button"
                                className={`${secondaryBtn} !px-2.5 !py-1 !text-rose-600`}
                                disabled={busy === s._id}
                                onClick={() => setConfirm({ kind: 'delete', staff: s })}
                              >
                                <Trash2 className="h-3.5 w-3.5" /> Delete
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {adding && (
        <Modal title="Give access" subtitle="A password is generated for you. You will see it once, on the next screen." onClose={() => setAdding(false)}>
          <ErrorNote text={formError} />
          <form onSubmit={create} className="space-y-3">
            <Field label="Full name" required>
              <input id="staff-name" className={inputClass} value={form.fullName} onChange={(e) => setForm((f) => ({ ...f, fullName: e.target.value }))} required />
            </Field>
            <Field label="Email" required hint="This is their login ID">
              <input id="staff-email" type="email" className={inputClass} value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} required />
            </Field>
            <Field label="Role" required>
              <select id="staff-role" className={inputClass} value={form.role} onChange={(e) => setForm((f) => ({ ...f, role: e.target.value as Role }))}>
                {ROLE_OPTIONS.map((r) => (
                  <option key={r} value={r}>
                    {ROLE_LABEL[r]}
                  </option>
                ))}
              </select>
            </Field>
            {form.role === 'ADMIN' && (
              <p className="rounded-xl bg-amber-50 dark:bg-amber-950/40 p-3 text-xs font-semibold text-amber-800 dark:text-amber-300">
                Admins can see and change everything, including giving and removing other people's access. Only give this to people you fully trust.
              </p>
            )}
            <div className="flex justify-end gap-2 pt-1">
              <button type="button" className={secondaryBtn} onClick={() => setAdding(false)}>
                Cancel
              </button>
              <button type="submit" className={primaryBtn} disabled={busy === 'new'}>
                <KeyRound className="h-3.5 w-3.5" /> {busy === 'new' ? 'Creating…' : 'Create login'}
              </button>
            </div>
          </form>
        </Modal>
      )}

      {confirm && (
        <Modal
          title={
            confirm.kind === 'reset'
              ? `Reset ${confirm.staff.fullName}'s password?`
              : confirm.kind === 'delete'
                ? `Delete ${confirm.staff.fullName}'s login permanently?`
                : `Remove ${confirm.staff.fullName}'s access?`
          }
          subtitle={
            confirm.kind === 'reset'
              ? 'A new password is generated and their old one stops working. Anyone signed in with the old password is signed out.'
              : confirm.kind === 'delete'
                ? `${confirm.staff.email} will be deleted and cannot be restored. Batches they taught will show no trainer. Things they created (jobs, banners, attendance taken) are kept.`
                : 'They are signed out within seconds and cannot log in again until you restore access. Their batches and history stay.'
          }
          onClose={() => setConfirm(null)}
        >
          <div className="flex justify-end gap-2">
            <button type="button" className={secondaryBtn} onClick={() => setConfirm(null)}>
              Cancel
            </button>
            <button
              type="button"
              className={`${primaryBtn} ${confirm.kind !== 'reset' ? '!bg-rose-600 hover:!bg-rose-700' : ''}`}
              disabled={busy === confirm.staff._id}
              onClick={() =>
                confirm.kind === 'reset' ? resetPassword(confirm.staff) : confirm.kind === 'delete' ? deleteAccount(confirm.staff) : setActive(confirm.staff, false)
              }
            >
              {confirm.kind === 'reset' ? 'Generate new password' : confirm.kind === 'delete' ? 'Delete permanently' : 'Remove access'}
            </button>
          </div>
        </Modal>
      )}

      {reveal && <PasswordReveal staff={reveal.staff} password={reveal.password} onClose={() => setReveal(null)} />}
      {toast.node}
    </div>
  );
};
